onChange.script:
# Closure method changed via the Change Closure Mode changeover: RESET the
# parts-in-tray field to the newly-selected config default PartsPerTray
# (overwrites any prior/stale value; fgConfig.onChange only prefills empty).
method = self.session.custom.closureMethod
if not method:
	return
container = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.container) or {}
itemId = container.get("ItemId") or self.view.custom.selectedFinishedGoodItemId
if not itemId:
	return
cfg = BlueRidge.Parts.ContainerConfig.getByItemAndMethodOrEmpty(itemId, method) or {}
ppt = cfg.get("PartsPerTray")
d = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.draft) or {}
self.view.custom.draft = {"partsCount": ppt if ppt else "", "trayPosition": d.get("trayPosition") or ""}
# Bump refreshToken too -- container.TraysPerContainer/ClosedTrays (the tray-of-tray
# label numbers) would otherwise stay on the pre-switch query result until some other
# event happens to refresh it.
self.view.custom.refreshToken = (self.view.custom.refreshToken or 0) + 1

